| cesc_aura_distribuir | CREATE OR REPLACE FUNCTION cesc.cesc_aura_distribuir(p_token character varying, p_ano_lectivo character varying)<br> RETURNS json<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br>AS $function$<br>DECLARE<br>    v_user cesc.utilizadores;<br>    v_alocacao record;<br>    v_sala record;<br>    v_inscricao record;<br>    v_inscricoes uuid[];<br>    v_idx int;<br>    v_alunos_na_sala int;<br>    v_num_seq int := 0;<br>    v_total_distribuidos int := 0;<br>    v_aluno_id uuid;<br>    v_matricula_id uuid;<br>BEGIN<br>    v_user := cesc.validar_sessao_role(p_token, ARRAY['diretor', 'sub_diretor']);<br>    IF v_user IS NULL THEN RETURN json_build_object('ok', false, 'erro', 'Não autorizado.'); END IF;<br><br>    -- Lê todas as alocações, sem filtrar pelo ano<br>    FOR v_alocacao IN <br>        SELECT * FROM cesc.alocacao_salas<br>    LOOP<br>        -- Busca as inscrições matricula_paga que correspondem à alocação<br>        SELECT array_agg(i.id ORDER BY i.nome_completo)<br>        INTO v_inscricoes<br>        FROM cesc.inscricoes i<br>        WHERE i.ano_lectivo = p_ano_lectivo<br>          AND i.estado = 'matricula_paga'<br>          AND i.classe_pretendida = v_alocacao.classe<br>          AND (i.curso_pretendido = v_alocacao.curso OR v_alocacao.curso IS NULL);<br><br>        IF v_inscricoes IS NULL THEN CONTINUE; END IF;<br><br>        v_idx := 1;<br>        FOR v_sala IN <br>            SELECT s.id, s.capacidade <br>            FROM cesc.salas s<br>            WHERE s.turno = v_alocacao.turno <br>              AND s.pavilhao = v_alocacao.pavilhao<br>              AND CAST(regexp_replace(s.nome_sala, '\\D', '', 'g') AS integer) BETWEEN v_alocacao.sala_inicio AND v_alocacao.sala_fim<br>            ORDER BY s.nome_sala<br>        LOOP<br>            v_alunos_na_sala := 0;<br>            WHILE v_idx <= array_length(v_inscricoes, 1) AND v_alunos_na_sala < v_sala.capacidade LOOP<br>                v_num_seq := v_num_seq + 1;<br><br>                -- Buscar o aluno_id e a matrícula<br>                SELECT aluno_id INTO v_aluno_id FROM cesc.inscricoes WHERE id = v_inscricoes[v_idx];<br><br>                -- Verifica se a matrícula já existe<br>                SELECT id INTO v_matricula_id FROM cesc.matriculas <br>                WHERE aluno_id = v_aluno_id AND ano_lectivo = p_ano_lectivo;<br><br>                -- Se não existir, cria a matrícula<br>                IF v_matricula_id IS NULL THEN<br>                    INSERT INTO cesc.matriculas (aluno_id, ano_lectivo, classe, turma, estado, curso)<br>                    SELECT v_aluno_id, p_ano_lectivo, classe_pretendida, 'A', 'activo', curso_pretendido<br>                    FROM cesc.inscricoes WHERE id = v_inscricoes[v_idx]<br>                    RETURNING id INTO v_matricula_id;<br>                END IF;<br><br>                -- Atualiza a matrícula com a sala e número<br>                UPDATE cesc.matriculas <br>                SET sala_id = v_sala.id, numero_aluno = v_num_seq<br>                WHERE id = v_matricula_id;<br><br>                -- Muda o estado da inscrição para matriculado<br>                UPDATE cesc.inscricoes<br>                SET estado = 'matriculado', matriculado = true, data_matricula = now()<br>                WHERE id = v_inscricoes[v_idx];<br><br>                v_idx := v_idx + 1;<br>                v_alunos_na_sala := v_alunos_na_sala + 1;<br>                v_total_distribuidos := v_total_distribuidos + 1;<br>            END LOOP;<br><br>            IF v_idx > array_length(v_inscricoes, 1) THEN EXIT; END IF;<br>        END LOOP;<br>    END LOOP;<br><br>    RETURN json_build_object('ok', true, 'distribuidos', v_total_distribuidos);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               |
| cesc_aura_julgar     | CREATE OR REPLACE FUNCTION cesc.cesc_aura_julgar(p_token character varying, p_ano_lectivo character varying)<br> RETURNS json<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br>AS $function$<br>DECLARE<br>    v_user cesc.utilizadores;<br>    v_aluno record;<br>    v_regra record;<br>    v_neg_crit int;<br>    v_neg_sec int;<br>    v_aprovado boolean;<br>    v_qtd int := 0;<br>    v_aprovados int := 0;<br>    v_reprovados int := 0;<br>BEGIN<br>    v_user := cesc.validar_sessao_role(p_token, ARRAY['diretor', 'sub_diretor']);<br>    IF v_user IS NULL THEN RETURN json_build_object('ok', false, 'erro', 'Não autorizado.'); END IF;<br><br>    FOR v_aluno IN <br>        SELECT i.id as inscricao_id, i.aluno_id, i.classe_pretendida, i.curso_pretendido<br>        FROM cesc.inscricoes i<br>        WHERE i.ano_lectivo = p_ano_lectivo AND i.estado = 'matricula_paga' <br>          AND (i.tipo IS NULL OR i.tipo = 'novo')<br>    LOOP<br>        v_qtd := v_qtd + 1;<br><br>        -- Buscar a regra da classe/curso<br>        SELECT * INTO v_regra FROM cesc.regras_aura <br>        WHERE classe = v_aluno.classe_pretendida <br>          AND (curso = v_aluno.curso_pretendido OR curso IS NULL)<br>        LIMIT 1;<br><br>        IF NOT FOUND THEN<br>            UPDATE cesc.inscricoes SET tipo = 'reprovado', motivo_rejeicao = 'Sem regra AURA configurada' WHERE id = v_aluno.inscricao_id;<br>            v_reprovados := v_reprovados + 1;<br>            CONTINUE;<br>        END IF;<br><br>        -- Contar negativas CRÍTICAS (Lendo da Grelha Curricular)<br>        SELECT count(*) INTO v_neg_crit <br>        FROM cesc.notas_trimestrais nt <br>        JOIN cesc.matriculas m ON m.id = nt.matricula_id <br>        JOIN cesc.disciplinas d ON d.nome = nt.disciplina<br>        JOIN cesc.grelha_curricular g ON g.disciplina_id = d.id<br>        JOIN cesc.classes c ON c.id = g.classe_id<br>        LEFT JOIN cesc.cursos cu ON cu.id = g.curso_id<br>        WHERE m.aluno_id = v_aluno.aluno_id <br>          AND m.ano_lectivo = p_ano_lectivo<br>          AND nt.mfd < 10 <br>          AND g.critica = true<br>          AND c.nome = v_aluno.classe_pretendida<br>          AND (cu.sigla = v_aluno.curso_pretendido OR v_aluno.curso_pretendido IS NULL);<br>        <br>        -- Contar negativas SECUNDÁRIAS (Lendo da Grelha Curricular)<br>        SELECT count(*) INTO v_neg_sec <br>        FROM cesc.notas_trimestrais nt <br>        JOIN cesc.matriculas m ON m.id = nt.matricula_id <br>        JOIN cesc.disciplinas d ON d.nome = nt.disciplina<br>        JOIN cesc.grelha_curricular g ON g.disciplina_id = d.id<br>        JOIN cesc.classes c ON c.id = g.classe_id<br>        LEFT JOIN cesc.cursos cu ON cu.id = g.curso_id<br>        WHERE m.aluno_id = v_aluno.aluno_id <br>          AND m.ano_lectivo = p_ano_lectivo<br>          AND nt.mfd < 10 <br>          AND g.critica = false<br>          AND c.nome = v_aluno.classe_pretendida<br>          AND (cu.sigla = v_aluno.curso_pretendido OR v_aluno.curso_pretendido IS NULL);<br><br>        v_aprovado := (v_neg_crit <= v_regra.max_negativas_criticas) AND (v_neg_sec <= v_regra.max_negativas_secundarias);<br><br>        IF v_aprovado THEN<br>            UPDATE cesc.inscricoes SET tipo = 'aprovado', motivo_rejeicao = NULL WHERE id = v_aluno.inscricao_id;<br>            v_aprovados := v_aprovados + 1;<br>        ELSE<br>            UPDATE cesc.inscricoes SET tipo = 'reprovado', motivo_rejeicao = 'Reprovado por excesso de negativas (' \|\| v_neg_crit \|\| ' críticas, ' \|\| v_neg_sec \|\| ' secundárias)' WHERE id = v_aluno.inscricao_id;<br>            v_reprovados := v_reprovados + 1;<br>        END IF;<br>    END LOOP;<br><br>    RETURN json_build_object('ok', true, 'total', v_qtd, 'aprovados', v_aprovados, 'reprovados', v_reprovados);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            |
| cesc_aura_transicao  | CREATE OR REPLACE FUNCTION cesc.cesc_aura_transicao(p_token character varying, p_ano_lectivo_actual character varying, p_novo_ano_lectivo character varying)<br> RETURNS json<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br>AS $function$<br>DECLARE<br>    v_user cesc.utilizadores;<br>    v_aluno record;<br>    v_nova_classe varchar;<br>    v_novo_curso varchar;<br>    v_qtd int := 0;<br>    v_criados int := 0;<br>BEGIN<br>    v_user := cesc.validar_sessao_role(p_token, ARRAY['diretor', 'sub_diretor']);<br>    IF v_user IS NULL THEN RETURN json_build_object('ok', false, 'erro', 'Não autorizado.'); END IF;<br><br>    FOR v_aluno IN <br>        SELECT i.id, i.aluno_id, i.classe_pretendida, i.curso_pretendido, i.tipo, <br>               i.referencia, i.bi_numero, i.nome_completo, i.data_nascimento, <br>               i.genero, i.telefone, i.email, i.nome_encarregado, i.parentesco, <br>               i.telefone_encarregado, i.bi_encarregado, i.endereco, i.como_soube, <br>               i.doc_bi_frente_url, i.doc_bi_verso_url, i.doc_certificado_url, <br>               i.doc_foto_url, i.media_certificado<br>        FROM cesc.inscricoes i<br>        WHERE i.ano_lectivo = p_ano_lectivo_actual <br>          AND i.estado = 'matriculado' <br>          AND (i.tipo = 'aprovado' OR i.tipo = 'reprovado')<br>    LOOP<br>        v_qtd := v_qtd + 1;<br><br>        -- REGRA: 9ª e 12ª não transitam. Ficam no histórico.<br>        IF v_aluno.classe_pretendida = '9ª Classe' OR v_aluno.classe_pretendida = '12ª Classe' THEN<br>            CONTINUE;<br>        END IF;<br><br>        -- Determinar a nova classe<br>        IF v_aluno.tipo = 'reprovado' THEN<br>            v_nova_classe := v_aluno.classe_pretendida;<br>            v_novo_curso := v_aluno.curso_pretendido;<br>        ELSE<br>            IF v_aluno.classe_pretendida = '8ª Classe' THEN<br>                v_nova_classe := '9ª Classe';<br>                v_novo_curso := NULL;<br>            ELSIF v_aluno.classe_pretendida = '9ª Classe' THEN<br>                v_nova_classe := '10ª Classe';<br>                v_novo_curso := 'C.F.B'; -- Curso padrão<br>            ELSIF v_aluno.classe_pretendida = '10ª Classe' THEN<br>                v_nova_classe := '11ª Classe';<br>                v_novo_curso := v_aluno.curso_pretendido;<br>            ELSIF v_aluno.classe_pretendida = '11ª Classe' THEN<br>                v_nova_classe := '12ª Classe';<br>                v_novo_curso := v_aluno.curso_pretendido;<br>            ELSE<br>                CONTINUE; -- Classe não reconhecida, ignora<br>            END IF;<br>        END IF;<br><br>        -- Evitar duplicação: verifica se já foi criada uma inscrição para este aluno no novo ano<br>        IF NOT EXISTS (<br>            SELECT 1 FROM cesc.inscricoes <br>            WHERE aluno_id = v_aluno.aluno_id <br>              AND ano_lectivo = p_novo_ano_lectivo<br>        ) THEN<br>            -- Cria a nova inscrição, copiando os dados, com estado 'matricula_paga'<br>            INSERT INTO cesc.inscricoes (<br>                referencia, bi_numero, nome_completo, data_nascimento, genero, <br>                telefone, email, nome_encarregado, parentesco, telefone_encarregado, <br>                bi_encarregado, endereco, classe_pretendida, curso_pretendido, <br>                ano_lectivo, como_soube, doc_bi_frente_url, doc_bi_verso_url, <br>                doc_certificado_url, doc_foto_url, estado, aluno_id, data_submissao, <br>                media_certificado, tipo, inscricao_paga<br>            ) VALUES (<br>                'CESC-' \|\| p_novo_ano_lectivo \|\| '-' \|\| LPAD((SELECT COUNT(*) + 1 FROM cesc.inscricoes)::text, 5, '0'), -- Gera uma referência provisória<br>                v_aluno.bi_numero, v_aluno.nome_completo, v_aluno.data_nascimento, v_aluno.genero,<br>                v_aluno.telefone, v_aluno.email, v_aluno.nome_encarregado, v_aluno.parentesco, <br>                v_aluno.telefone_encarregado, v_aluno.bi_encarregado, v_aluno.endereco, <br>                v_nova_classe, v_novo_curso, p_novo_ano_lectivo, v_aluno.como_soube, <br>                v_aluno.doc_bi_frente_url, v_aluno.doc_bi_verso_url, v_aluno.doc_certificado_url, <br>                v_aluno.doc_foto_url, 'matricula_paga', v_aluno.aluno_id, now(), <br>                v_aluno.media_certificado, 'novo', true<br>            );<br>            v_criados := v_criados + 1;<br>        END IF;<br>    END LOOP;<br><br>    RETURN json_build_object('ok', true, 'total_analisados', v_qtd, 'novas_inscricoes_criadas', v_criados);<br>END;<br>$function$<br> |